import Foundation
import CryptoKit

/// Current user-facing tracks[].frozen media. Generated bytes only; no codec,
/// audio engine, application, device, or installed plug-in is used.
@main struct TrackFreezeMediaTests {
    struct Failure: Error, CustomStringConvertible { let description: String }
    static func check(_ value: @autoclosure () throws -> Bool, _ message: String) throws { if try !value() { throw Failure(description: message) } }
    static func json(_ value: Any) throws -> Data { try JSONSerialization.data(withJSONObject:value,options:[.sortedKeys,.fragmentsAllowed]) }
    static func digest(_ data: Data) -> String { SHA256.hash(data:data).map { String(format:"%02x",$0) }.joined() }
    static func record(_ project: [String:Any]) -> [String:Any] { (project["tracks"] as! [[String:Any]])[0]["frozen"] as! [String:Any] }
    static func entries(_ project: [String:Any]) -> [[String:Any]] {
        let frozen=record(project)
        return [frozen] + (frozen["patternPrints"] as! [[String:Any]]).flatMap { [$0,$0["loop"] as! [String:Any]] }
    }
    static func fixture(_ root: URL) throws -> [String:Any] {
        try FileManager.default.createDirectory(at:root,withIntermediateDirectories:true)
        let files=try (0..<5).map { index -> [String:Any] in
            let path=root.appendingPathComponent(index == 0 ? "song-print" : "pattern-\(index).wav"),data=Data([UInt8(index),1,2,3,4])
            try data.write(to:path);return ["path":path.path,"sha256":digest(data),"frames":192000]
        }
        var frozen=files[0];frozen.merge(["version":1,"id":"captured","sampleRate":48000.0,"frames":288000,"musicalFrames":192000,"tailFrames":96000,
            "musicalEndBeat":8.0,"tailSeconds":2.0,"dormantPluginIDs":["saved-plugin"],"fingerprint":"unchanged-source-fingerprint","mixMode":"flat","createdAt":"fixture",
            "patternPrints":[["pattern":0,"path":files[1]["path"]!,"sha256":files[1]["sha256"]!,"frames":192000,"passFrames":96000,"passes":2,"loop":files[2]],
                             ["pattern":1,"path":files[3]["path"]!,"sha256":files[3]["sha256"]!,"frames":192000,"passFrames":96000,"passes":2,"loop":files[4]]],
            "unprintedPatterns":[],"opaqueExtension":["path":"opaque.wav"]]) { _,new in new }
        return ["version":1,"bpm":120.0,"tracks":[["id":0,"frozen":frozen]],"instruments":[["id":0,"type":"synth"]],
            "patterns":[["id":0,"length":16,"steps":[[]]],["id":1,"length":16,"steps":[[]]]],"sequence":[0,1],
            "audioPlugins":[["id":"saved-plugin","state":["path":"vendor.wav","frozen":["path":"vendor-print.wav"]]]]]
    }
    static func rejects(_ body: ()throws->Void,_ message:String)throws{var rejected=false;do{try body()}catch{rejected=true};try check(rejected,message)}
    static func portability(_ root:URL)throws{
        let original=try fixture(root.appendingPathComponent("originals")), before=try json(original),store=try ProjectStore(directory:root.appendingPathComponent("support"))
        let destination=root.appendingPathComponent("package/Frozen.supertracker");try FileManager.default.createDirectory(at:destination.deletingLastPathComponent(),withIntermediateDirectories:true)
        let saved=try store.save(to:destination,snapshot:original), stored=try JSONSerialization.jsonObject(with:Data(contentsOf:destination)) as! [String:Any]
        try check(entries(stored).allSatisfy { ($0["path"] as! String).hasPrefix("Frozen.media/") },"Song, pattern head and pattern loop prints must all be collected")
        try check(entries(saved).allSatisfy { ($0["path"] as! String).hasPrefix(destination.deletingLastPathComponent().path) },"Live aliases must point to copied media")
        try check(try json(original)==before,"Collect must preserve the input/Undo project")
        try check(try json(saved["audioPlugins"]!)==json(original["audioPlugins"]!),"Dormant plug-in state must remain byte-equivalent JSON")
        try check(record(saved)["fingerprint"] as? String == record(original)["fingerprint"] as? String,"Collect cannot recertify a captured source fingerprint")
        try check(try json(record(saved)["opaqueExtension"]!)==json(record(original)["opaqueExtension"]!),"Unknown fields inside frozen metadata remain opaque")
        _=try store.save(to:destination)
        try check(try FileManager.default.contentsOfDirectory(atPath:destination.deletingPathExtension().appendingPathExtension("media").path).count==5,"Repeated save must not duplicate prints")
        let second=root.appendingPathComponent("second/Again.supertracker");try FileManager.default.createDirectory(at:second.deletingLastPathComponent(),withIntermediateDirectories:true)
        _=try store.save(to:second)
        let moved=root.appendingPathComponent("moved");try FileManager.default.moveItem(at:second.deletingLastPathComponent(),to:moved)
        try FileManager.default.removeItem(at:root.appendingPathComponent("originals"));try FileManager.default.removeItem(at:destination.deletingLastPathComponent())
        let opened=try store.read(moved.appendingPathComponent("Again.supertracker"))
        for entry in entries(opened){let path=entry["path"] as! String;try check(path.hasPrefix(moved.path),"Relative print aliases must resolve inside moved package");try check(try digest(Data(contentsOf:URL(fileURLWithPath:path)))==entry["sha256"] as! String,"All moved print bytes must equal captured hashes")}
    }
    static func changedAndMissing(_ root:URL)throws{
        let original=try fixture(root.appendingPathComponent("originals")), store=try ProjectStore(directory:root.appendingPathComponent("support")),destination=root.appendingPathComponent("Rejected.supertracker")
        try store.update(original);let before=try json(store.project!)
        let loop=entries(original)[2]["path"] as! String;try Data([99]).write(to:URL(fileURLWithPath:loop))
        try rejects({_ = try store.save(to:destination)},"Changed pattern-loop print bytes must reject Save instead of carrying an old SHA onto a new file")
        try check(store.dirty && store.url == nil && !FileManager.default.fileExists(atPath:destination.path) && (try json(store.project!))==before,"Failed print verification must preserve dirty state and primary bytes")
        for entry in entries(original){try FileManager.default.removeItem(atPath:entry["path"] as! String)}
        let saved=try store.save(to:destination)
        try check(try json(record(saved))==json(record(original)),"Missing print references must remain repairable without changing recorded hashes")
    }
    static func relink(_ root:URL)throws{
        let original=try fixture(root.appendingPathComponent("originals")),before=try json(original)
        let first=MediaRelinker.inspect(original),refs=first["references"] as! [[String:Any]]
        try check(refs.count==5 && first["missingCount"] as? Int == 0,"Current song/head/loop prints must appear as verified media references")
        try check(refs.allSatisfy{$0["kind"] as? String == "freeze" && $0["requiresExactContent"] as? Bool == true},"Every print requires exact-content recovery")
        let copied=root.appendingPathComponent("copies");try FileManager.default.moveItem(at:root.appendingPathComponent("originals"),to:copied)
        let selections=refs.map{ref->[String:Any] in ["id":ref["id"]!,"from":ref["path"]!,"to":copied.appendingPathComponent(URL(fileURLWithPath:ref["path"] as! String).lastPathComponent).path]}
        let applied=try MediaRelinker.apply(original,selections:selections),updated=applied["project"] as! [String:Any]
        try check(applied["changed"] as? Int==5 && (applied["remaining"] as! [Any]).isEmpty,"One atomic relink must repair every print alias")
        try check(entries(updated).allSatisfy{($0["path"] as! String).hasPrefix(copied.path)},"Head and loop aliases must reach their exact selected paths")
        try check(try json(original)==before && json(updated["audioPlugins"]!)==json(original["audioPlugins"]!),"Relink preserves original canonical/Undo and opaque dormant state")
        var invalid=selections;let wrong=root.appendingPathComponent("wrong.wav");try Data([88]).write(to:wrong)
        invalid[4]["to"]=wrong.path;invalid[4]["allowDifferentContent"]=true
        try rejects({_ = try MediaRelinker.apply(original,selections:invalid)},"Different-content override cannot replace a frozen pattern loop")
        try check(try json(original)==before,"Failed multi-file relink remains atomic")
    }
    static func freshness(_ root:URL)throws{
        var original=try fixture(root.appendingPathComponent("prints"))
        let sample=root.appendingPathComponent("source.wav"),bytes=Data([42,43,44]);try bytes.write(to:sample)
        original["instruments"]=[["id":0,"samplePath":sample.path,"zones":[["path":sample.path,"samplePath":sample.path]]]]
        original["audioClips"]=[["id":"clip","track":0,"startBeat":0.0,"durationBeats":4.0,"path":sample.path,
            "takeSet":["version":1,"activeID":"a","takes":[["id":"a","path":sample.path],["id":"b","path":sample.path]]]]]
        original["mediaManifest"]=[["path":sample.path,"sha256":digest(bytes)]]
        var tracks=original["tracks"] as! [[String:Any]],frozen=record(original)
        frozen["fingerprint"]=try AudioFreezeTrackFingerprint.fingerprint(original,index:0);tracks[0]["frozen"]=frozen;original["tracks"]=tracks
        func fresh(_ value:[String:Any])throws->Bool{try record(value)["fingerprint"] as? String == AudioFreezeTrackFingerprint.fingerprint(value,index:0)}
        let store=try ProjectStore(directory:root.appendingPathComponent("support")),file=root.appendingPathComponent("Fresh.supertracker")
        let saved=try store.save(to:file,snapshot:original),stored=try JSONSerialization.jsonObject(with:Data(contentsOf:file)) as! [String:Any],opened=try store.read(file)
        try check(try fresh(saved) && fresh(stored) && fresh(opened),"Only verified copy and package aliases must preserve previously fresh captures across sample/zone/clip/take paths")
        let package=root.appendingPathComponent("package"),movedPackage=root.appendingPathComponent("relocated-package")
        try FileManager.default.createDirectory(at:package,withIntermediateDirectories:true)
        _=try store.save(to:package.appendingPathComponent("Moved.supertracker"))
        try FileManager.default.moveItem(at:package,to:movedPackage)
        try check(try fresh(store.read(movedPackage.appendingPathComponent("Moved.supertracker"))),"Moving a complete collected folder must retain source freshness")
        var stale=original;var patterns=stale["patterns"] as! [[String:Any]];patterns[0]["steps"]=[[["note":60]]];stale["patterns"]=patterns
        let staleFile=root.appendingPathComponent("Stale.supertracker"),staleSaved=try store.save(to:staleFile,snapshot:stale)
        try check(try !fresh(staleSaved) && !fresh(store.read(staleFile)),"Save and Open may never recertify an already stale source")
        try check(record(staleSaved)["fingerprint"] as? String == frozen["fingerprint"] as? String,"Stale fingerprint bytes must remain unchanged")
        let replacement=root.appendingPathComponent("identical.wav");try bytes.write(to:replacement);try FileManager.default.removeItem(at:sample)
        let refs=MediaRelinker.inspect(original)["references"] as! [[String:Any]]
        let selections=refs.filter{$0["kind"] as? String != "freeze"}.map{["id":$0["id"]!,"from":$0["path"]!,"to":replacement.path]}
        let moved=try MediaRelinker.apply(original,selections:selections)["project"] as! [String:Any]
        try check(try fresh(moved),"Full-hash relinking of exact source aliases must preserve freshness")
        let wrong=root.appendingPathComponent("different.wav");try Data([9,9,9]).write(to:wrong)
        let deliberate=selections.map{selection->[String:Any] in var result=selection;result["to"]=wrong.path;result["allowDifferentContent"]=true;return result}
        let changed=try MediaRelinker.apply(original,selections:deliberate)["project"] as! [String:Any]
        try check(try !fresh(changed),"An explicit different-content source replacement must remain stale")
    }
    static func main()throws{
        let root=FileManager.default.temporaryDirectory.appendingPathComponent("TrackFreezeMedia-\(UUID().uuidString)");try FileManager.default.createDirectory(at:root,withIntermediateDirectories:true);defer{try? FileManager.default.removeItem(at:root)}
        var failures=0
        for(name,run) in [("song/head/loop print collect, repeat Save As and moved-folder Open",portability),("changed print rejection and missing-media repairability",changedAndMissing),("bounded exact-hash print inventory and atomic relink",relink),("verified source aliases preserve freshness without recertifying changes",freshness)]{
            let folder=root.appendingPathComponent(String(failures)+name.prefix(4));try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true)
            do{try run(folder);print("PASS \(name)")}catch{failures+=1;print("FAIL \(name): \(error)")}
        }
        print("Current track freeze media: \(4-failures)/4 groups passed")
        if failures>0{exit(1)}
    }
}
